<?php
namespace Src\Facturacion\Application\Services;
use Brick\Math\BigDecimal;use Brick\Math\RoundingMode;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;use Src\Facturacion\Infrastructure\Models\FacturaOrdenEloquentModel;use Src\Facturacion\Infrastructure\Models\FacturaOrdenHistorialEloquentModel;use Src\Facturacion\Infrastructure\Models\FacturaOrdenLineaEloquentModel;use Src\OrdenTrabajo\Infrastructure\Models\OrdenTrabajoEloquentModel;
class GestionarFacturaOrden
{
    public function emitir(OrdenTrabajoEloquentModel$orden,array$datos,string$usuarioId):FacturaOrdenEloquentModel
    {
        return DB::transaction(function()use($orden,$datos,$usuarioId){$bloqueada=OrdenTrabajoEloquentModel::with(['cliente','vehiculo'])->whereKey($orden->id)->lockForUpdate()->firstOrFail();if(!in_array($bloqueada->estado,['finalizada','entregada'],true))throw ValidationException::withMessages(['orden'=>'Solo se puede facturar una orden finalizada o entregada.']);if(FacturaOrdenEloquentModel::where('orden_id',$bloqueada->id)->where('estado','emitida')->exists())throw ValidationException::withMessages(['orden'=>'La orden ya tiene una factura vigente.']);$lineas=[];$subtotal=BigDecimal::zero();foreach(DB::table('orden_servicios')->where('orden_id',$bloqueada->id)->where('estado','<>','cancelado')->get()as$s){$valor=BigDecimal::of((string)$s->precio_acordado)->toScale(2);$subtotal=$subtotal->plus($valor);$lineas[]=['tipo'=>'servicio','referencia_id'=>$s->servicio_id,'codigo'=>null,'descripcion'=>$s->nombre_servicio,'cantidad'=>'1.000','precio_unitario'=>(string)$valor,'subtotal'=>(string)$valor];}foreach(DB::table('orden_repuestos as u')->join('repuestos as r','r.id','=','u.repuesto_id')->where('u.orden_id',$bloqueada->id)->whereNull('u.revertido_en')->get(['u.repuesto_id','u.cantidad','u.precio_unitario','r.codigo','r.nombre'])as$p){$valor=BigDecimal::of((string)$p->cantidad)->multipliedBy(BigDecimal::of((string)$p->precio_unitario))->toScale(2,RoundingMode::HALF_UP);$subtotal=$subtotal->plus($valor);$lineas[]=['tipo'=>'repuesto','referencia_id'=>$p->repuesto_id,'codigo'=>$p->codigo,'descripcion'=>$p->nombre,'cantidad'=>$p->cantidad,'precio_unitario'=>$p->precio_unitario,'subtotal'=>(string)$valor];}if(!$lineas||$subtotal->isZero())throw ValidationException::withMessages(['orden'=>'La orden no tiene conceptos facturables.']);$descuento=BigDecimal::of((string)$datos['descuento'])->toScale(2,RoundingMode::HALF_UP);if($descuento->isGreaterThan($subtotal))throw ValidationException::withMessages(['descuento'=>'El descuento no puede superar el subtotal.']);$base=$subtotal->minus($descuento);$tasa=BigDecimal::of((string)$datos['tasa_impuesto'])->toScale(2,RoundingMode::HALF_UP);$impuesto=$base->multipliedBy($tasa)->dividedBy('100',2,RoundingMode::HALF_UP);$total=$base->plus($impuesto);$pagado=BigDecimal::of((string)DB::table('pagos')->where('orden_id',$bloqueada->id)->where('estado','registrado')->sum('monto'));if($total->isLessThan($pagado))throw ValidationException::withMessages(['descuento'=>'El total facturado no puede quedar por debajo del monto ya pagado.']);$sufijo=mb_strtoupper(substr(str_replace('-','',(string)str()->uuid()),0,8));$cliente=$bloqueada->cliente;$factura=FacturaOrdenEloquentModel::create(['numero'=>'FV-'.now()->format('Ymd').'-'.$sufijo,'orden_id'=>$bloqueada->id,'cliente_tipo_documento'=>$cliente->tipo_documento,'cliente_documento'=>$cliente->numero_documento,'cliente_nombre'=>$cliente->razon_social,'cliente_direccion'=>$cliente->direccion,'cliente_email'=>$cliente->email,'vehiculo_placa'=>$bloqueada->vehiculo->placa,'subtotal'=>(string)$subtotal->toScale(2),'descuento'=>(string)$descuento,'base_impuesto'=>(string)$base,'tasa_impuesto'=>(string)$tasa,'impuesto'=>(string)$impuesto,'total'=>(string)$total,'moneda'=>'COP','estado'=>'emitida','emitida_en'=>now(),'vence_en'=>$datos['vence_en']??null,'observaciones'=>$datos['observaciones']??null,'emitida_por'=>$usuarioId]);foreach($lineas as$linea)FacturaOrdenLineaEloquentModel::create([...$linea,'factura_id'=>$factura->id]);FacturaOrdenHistorialEloquentModel::create(['factura_id'=>$factura->id,'evento'=>'emitida','datos'=>['total'=>$factura->total,'orden'=>$bloqueada->numero],'usuario_id'=>$usuarioId]);return$factura;});
    }
    public function anular(FacturaOrdenEloquentModel$factura,string$motivo,string$usuarioId):FacturaOrdenEloquentModel
    {
        return DB::transaction(function()use($factura,$motivo,$usuarioId){$bloqueada=FacturaOrdenEloquentModel::whereKey($factura->id)->lockForUpdate()->firstOrFail();$orden=OrdenTrabajoEloquentModel::whereKey($bloqueada->orden_id)->lockForUpdate()->firstOrFail();if($orden->estado==='entregada')throw ValidationException::withMessages(['factura'=>'No se puede anular la factura después de entregar el vehículo.']);if($bloqueada->estado==='anulada')throw ValidationException::withMessages(['factura'=>'La factura ya fue anulada.']);if(DB::table('pagos')->where('orden_id',$bloqueada->orden_id)->where('estado','registrado')->exists())throw ValidationException::withMessages(['factura'=>'Primero anula los pagos vigentes de la orden.']);$bloqueada->update(['estado'=>'anulada','anulada_en'=>now(),'anulada_por'=>$usuarioId,'motivo_anulacion'=>$motivo]);FacturaOrdenHistorialEloquentModel::create(['factura_id'=>$bloqueada->id,'evento'=>'anulada','datos'=>['motivo'=>$motivo],'usuario_id'=>$usuarioId]);return$bloqueada;});
    }
}
